"""Source-faithful face-crop comparison; no cross-crop quality equivalence."""
from pathlib import Path
import json,shutil,html
from PIL import Image,ImageDraw
folder=Path('output/circle-head-240-face');old=Path('output/circle-head-240')
for suffix in ['source','target','sequence','common']:
 shutil.copy2(old/f'circle-{suffix}.png',folder/f'whole-head-{suffix}.png')
before=json.loads((old/'circle-compute.json').read_text());after=json.loads((folder/'circle-compute.json').read_text());e=json.loads((folder/'browser-evidence.json').read_text())
features=Image.new('RGB',(900,510),'#faf8ef');d=ImageDraw.Draw(features)
from math import ceil,floor
for row,key in enumerate(['eyes','nose','mouth']):
 for col,(directory,name,suffix) in enumerate([(old,'whole-head target','target'),(old,'whole-head strands','sequence'),(folder,'face-centered target','target'),(folder,'face-centered strands','sequence')]):
  box=json.loads((directory/'circle-settings.json').read_text())['portrait']['regions'][key]
  bounds=(ceil(box['left']*159),ceil(box['top']*159),floor((box['left']+box['width'])*159)+1,floor((box['top']+box['height'])*159)+1)
  crop=Image.open(directory/f'circle-{suffix}.png').crop(bounds).resize((210,120),Image.Resampling.BILINEAR)
  features.paste(crop,(col*225+4,row*170+30));d.text((col*225+4,row*170+8),name+' / '+key,fill='#18201d')
features.save(folder/'features.png')
body='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Ip Rasm face framing</title><style>body{font:16px system-ui;margin:24px;background:#faf8ef;color:#18201d;max-width:1200px}img{max-width:100%;height:auto}.native img{width:160px;height:160px}.native{display:flex;gap:12px;flex-wrap:wrap}.pair{display:flex;gap:18px;flex-wrap:wrap}.pair img{width:384px;height:384px}table{border-collapse:collapse}th,td{padding:10px;text-align:left;border-bottom:1px solid #dce2d4}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style><h1>Separate face-centered portrait</h1><p>Same original local photo,240unrotated pins,400×400mm board,0.1mm thread,160sampling,8physical sweeps/weight2 and32/160guards. Existing manual face rectangle is fitted with4mmclearance. Face zoom increases26.65%; manually marked eyes/nose/lips retain exactly the same source coordinates. Hair can be cropped; this is NOT whole-head containment. Old projects and progress remain preserved.</p><p><b>Quality and physical acceptance remain OPEN.</b> Face features are larger, but nose shading, lip separation and crossing strands remain weak. This changed crop changes the processed target. Native/common errors across different crops do not establish equivalent quality, and the extra1251connections are not a simplification.</p><h2>Whole-head source / target / full sequence, native160</h2><div class="native"><img src="whole-head-source.png"><img src="whole-head-target.png"><img src="whole-head-sequence.png"></div><h2>Face-centered source / target / full sequence, native160</h2><div class="native"><img src="circle-source.png"><img src="circle-target.png"><img src="circle-sequence.png"></div><h2>All actual strands, independently reconstructed at384</h2><div class="pair"><div><p>Whole head</p><img src="whole-head-common.png"></div><div><p>Face centered; hair may be cropped</p><img src="circle-common.png"></div></div><h2>Same source-relative anatomical windows</h2><p>Each manually marked window is enlarged identically to210×120; the number of native samples differs. No photo overlays, invented anatomy or result-specific sharpening.</p><img src="features.png"><h2>Assembly estimates and full computation</h2><table><tr><th>Variant</th><th>Connections</th><th>Thread</th><th>Full generation</th></tr>'''
for label,data in [('Whole head',before),('Face centered',after)]:body+=f"<tr><td>{label}</td><td>{data['connections']}</td><td>{data['meters']:.3f}m</td><td>{data['fullMs']/1000:.2f}s</td></tr>"
body+='</table><p>The face-centered estimate requires421.460m beyond600mstock; stock is a supply estimate rather than a generation stop. Sampled peak Node RSS417411072bytes is not an instantaneous/native-device memory measurement.</p><h2>Source and offline replay evidence</h2><pre>'+html.escape(json.dumps(e,indent=2))+'</pre><p><a href="circle-guide.json">Separate immutable project</a> · <a href="browser-evidence.json">Exact preview/coordinates/offline evidence</a> · <a href="../contour/report.html">Contour experiment</a> · <a href="http://127.0.0.1:4183/">Website</a></p><p>This diagnostic has JSON/PNG/native and common replay evidence. Its PDF has not been independently exported/checked in this increment. It is not accepted for physical assembly.</p></html>'
(folder/'report.html').write_text(body,encoding='utf8')
print(json.dumps(dict(hash=after['sequenceHash'],sourceCornerChecks=e['sourceCornerChecks'],offlineReplay=e['offlineReload'],qualityAcceptance='open')))
